import gmpy2
from factordb.factordb import FactorDB
from math import isqrt

def check_factordb(n):
    f = FactorDB(n)
    f.connect()
    return f.get_factor_list()

def is_perfect_power(n):
    # Check if n is a perfect power
    for b in range(2, int(gmpy2.log2(n))+1):
        a = gmpy2.iroot(n, b)
        if a[1]:  # if perfect root was found
            return True, b, int(a[0])
    return False, None, None

def find_small_factors(n, limit=1000000):
    factors = []
    for i in range(2, limit):
        while n % i == 0:
            factors.append(i)
            n //= i
        if n == 1:
            break
    return factors

